import React, { useState, useEffect } from "react";
import api from "@landinghub/api";
import LeadKanban from "../components/LeadKanban";
import "./Leads.css";

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [view, setView] = useState("kanban");
  const [loading, setLoading] = useState(true);

  const fetchLeads = async () => {
    setLoading(true);
    try {
      const res = await api.get("/api/leads");
      setLeads(res.data);
    } catch (err) {
      console.error("Lỗi lấy leads:", err);
    } finally {
      setLoading(false);
    }
  };

  const updateLead = async (id, field, value) => {
    try {
      await api.put(`/api/leads/${id}`, { [field]: value });
      setLeads((prev) =>
        prev.map((l) => (l._id === id ? { ...l, [field]: value } : l))
      );
    } catch (err) {
      alert("Cập nhật thất bại");
    }
  };

  const deleteLead = async (id) => {
    if (!window.confirm("Xóa lead này?")) return;
    try {
      await api.delete(`/api/leads/${id}`);
      setLeads((prev) => prev.filter((l) => l._id !== id));
    } catch (err) {
      alert("Xóa thất bại");
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  if (loading) return <p>Đang tải dữ liệu...</p>;

  return (
    <div className="lead-page">
      <div className="lead-toolbar">
        <h2>📊 Quản lý Leads</h2>
        <div>
          <button
            className={view === "list" ? "active" : ""}
            onClick={() => setView("list")}
          >
            📋 Danh sách
          </button>
          <button
            className={view === "kanban" ? "active" : ""}
            onClick={() => setView("kanban")}
          >
            🗂 Kanban
          </button>
          <button onClick={fetchLeads}>🔄 Làm mới</button>
        </div>
      </div>

      {view === "list" ? (
        <div className="lead-table">
          <table>
            <thead>
              <tr>
                <th>Tên</th>
                <th>Email</th>
                <th>Điện thoại</th>
                <th>Trạng thái</th>
                <th>Ghi chú</th>
                <th>Hành động</th>
              </tr>
            </thead>
            <tbody>
              {leads.map((lead) => (
                <tr key={lead._id}>
                  <td>{lead.name}</td>
                  <td>{lead.email}</td>
                  <td>{lead.phone}</td>
                  <td>
                    <span className={`badge status-${lead.status}`}>
                      {lead.status === "new" && "Mới"}
                      {lead.status === "processing" && "Đang xử lý"}
                      {lead.status === "converted" && "Chuyển đổi"}
                      {lead.status === "lost" && "Mất"}
                    </span>
                  </td>
                  <td>
                    <input
                      value={lead.notes || ""}
                      onChange={(e) =>
                        updateLead(lead._id, "notes", e.target.value)
                      }
                    />
                  </td>
                  <td>
                    <button onClick={() => deleteLead(lead._id)}>Xóa</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <LeadKanban
          leads={leads}
          onStatusChange={(id, val) => updateLead(id, "status", val)}
          onDelete={deleteLead}
        />
      )}
    </div>
  );
};

export default Leads;
